        rrb::push_leaf(ctx, root, tail)?
    };
    let cut = rrb::cut(ctx, tree, start, end)?;

/// 01-12「レコード」のフィールドを取り出す関数の行。
fn getters(
    module: &ModuleInfo,
    record: &ast::RecordDecl,
    resolved: &ResolveOutput,
    types: &TypeckOutput,
    out: &mut CoreProgram,
) -> Result<(), InternalError> {
    let adt = resolved
        .decls
        .get(record.id)
        .copied()
        .ok_or_else(|| error(format!("missing record decls for {:?}", record.id)))?;
    for (i, field) in record.fields.iter().enumerate() {
        let binding = resolved
            .decls
            .get(field.id)
            .copied()
            .ok_or_else(|| error(format!("missing field decls for {:?}", field.id)))?;
        let scheme = types
            .decl_types
            .get(binding)
            .cloned()
            .ok_or_else(|| error(format!("missing field scheme for {binding:?}")))?;
        let mut state = State::new(resolved, types, &mut out.body_count, scheme.clone());
        let r = state.var(
            None,
            scheme
                .params
                .first()
                .cloned()
                .ok_or_else(|| error("getter has no parameter"))?,
        )?;
        let z = state.var(None, scheme.ret.clone())?;
        let pattern = CorePat::Ctor {
            adt,
            tag: 0,
            args: record
                .fields
                .iter()
                .enumerate()
                .map(|(j, _)| {
                    if i == j {
                        CorePat::Var(z.id)
                    } else {
                        CorePat::Wild
                    }
                })
                .collect(),
        };
        let body = Comp {
            kind: CompKind::Match {
                scrutinee: variable(&r, field.span),
                rows: vec![MatchRow { pattern, arm: 0 }],
                arms: vec![MatchArm {
                    vars: vec![z.clone()],
                    guard: None,
                    body: returned(variable(&z, field.span)),
                }],
            },
            ty: scheme.ret.clone(),
            eff: EffectSet::empty(),
            origin: field.span,
        };
        let public = state.binding(binding)?.public;
        out.defs.push(Def {
            param_names: scheme.param_names.clone(),
            binding,
            name: name(
                module,
                public,
                &format!("{}.{}", record.name.text, field.name.text),
            )?,
            origin: origin(module, public),
            kind: DefKind::FieldGetter {
                record: adt,
                index: number(i)?,
            },
            type_params: scheme.type_params.iter().map(|p| p.name.clone()).collect(),
            effect_params: scheme.effect_params,
            dict_params: vec![],
            params: vec![r],
            ret: scheme.ret,
            eff: scheme.effects,
            body,
            span: field.span,
            var_count: state.vars,
        });

fn getter_definition(
    p: &CheckedProgram,
    core: &c::CoreProgram,
    d: &c::CoreDef,
    record: BindingId,
    index: u32,
) -> Value {
    let mut s = Surface::new(p, Some(d.ret.clone()), Vec::new());
    let adt = p.types.adts.get(record).unwrap();
    let constructor = adt.ctors.first().unwrap();
    assert_eq!(constructor.tag, 0);
    let fields = adt.record.as_ref().unwrap();
    assert_eq!(fields[usize::try_from(index).unwrap()].binding, d.binding);
    assert!(d.dict_params.is_empty());
    let args: Vec<_> = constructor.fields.iter().map(|t| s.ty(t)).collect();
    let mut decl = json!({"data":data_name(record),"ntys":adt.type_params.len(),"args":args});
    decl["fields"] = json!(fields.iter().map(|f| &f.name).collect::<Vec<_>>());
    let name = format!("{} ({})", d.name, fun_name(d.binding));
    if !s.outside.is_empty() {
        return json!({"name":name,"annotations":s.annotations,"scope":tagged("outOfScope",json!({"elements":s.outside}))});
    }
    let annotations = json!(s.annotations);
    let (actual, core_outside) = core_definition(s, core, d, 0);
    assert!(
        core_outside.is_empty(),
        "constant reference in generated accessor"
    );
    json!({"name":name,"annotations":annotations,"scope":tagged("accessor",json!({
        "name":fun_name(d.binding),"con":con_name(p, record,0),"k":index,"decl":decl,"core":actual}))})
}

